/// <summary>Delphi `TStringGrid` 的可测模型（列优先存储，越界抛 IndexOutOfRangeException ↔ Delphi EInvalidGridIndex）。</summary>
public interface IStringGrid
{
    int RowCount { get; set; }
    int ColCount { get; }
    string GetCell(int col, int row);
    void SetCell(int col, int row, string value);
}

/// <summary>Delphi `TStringGrid` 的最小实现（本车道单测用，也可承载窗体数据）。</summary>
public class TStringGridModel : IStringGrid
{
    private readonly List<string>[] _cols;

    public TStringGridModel(int colCount, int rowCount)
    {
        ColCount = colCount;
        _cols = new List<string>[colCount];
        for (int c = 0; c < colCount; c++)
        {
            _cols[c] = new List<string>();
            for (int r = 0; r < rowCount; r++) _cols[c].Add("");
        }
        RowCount = rowCount;
    }

    public int ColCount { get; }

    public int RowCount
    {
        get => _cols[0].Count;
        set
        {
            for (int c = 0; c < ColCount; c++)
            {
                while (_cols[c].Count < value) _cols[c].Add("");
                while (_cols[c].Count > value) _cols[c].RemoveAt(_cols[c].Count - 1);
            }
        }
    }

    /// <summary>Delphi `AddrGrid.Cells[Col, Row]`（列在前，行在后）。</summary>
    public string this[int col, int row]
    {
        get => GetCell(col, row);
        set => SetCell(col, row, value);
    }

    public string GetCell(int col, int row)
    {
        if (col < 0 || col >= ColCount) throw new IndexOutOfRangeException($"grid column {col} out of range 0..{ColCount - 1}");
        if (row < 0 || row >= RowCount) throw new IndexOutOfRangeException($"grid row {row} out of range 0..{RowCount - 1}");
        return _cols[col][row];
    }

    public void SetCell(int col, int row, string value)
    {
        if (col < 0 || col >= ColCount) throw new IndexOutOfRangeException($"grid column {col} out of range 0..{ColCount - 1}");
        if (row < 0 || row >= RowCount) throw new IndexOutOfRangeException($"grid row {row} out of range 0..{RowCount - 1}");
        _cols[col][row] = value;
    }
}

/// <summary>AddrEdit.pas 的非 UI 逻辑（可单测，等价于窗体事件的函数体）。</summary>
public static class AddrEditLogic
{
    /// <summary>AddrEdit.dfm: ColCount=9 / RowCount=9 / FixedCols=0。</summary>
    public const int ColCount = 9;

    public const int InitialRowCount = 9;

    /// <summary>AddrEdit.pas:38-50 `TFrmEditAddr.FormCreate`：ERowCount.Value := 8 并写表头。</summary>
    public static void FormCreate(IStringGrid grid)
    {
        grid.SetCell(0, 0, "角色选择网关地址");
        grid.SetCell(1, 0, "游戏网关");
        grid.SetCell(2, 0, "端口");
        grid.SetCell(3, 0, "游戏网关");
        grid.SetCell(4, 0, "端口");
        grid.SetCell(5, 0, "游戏网关");
        grid.SetCell(6, 0, "端口");
        grid.SetCell(7, 0, "游戏网关");
        grid.SetCell(8, 0, "端口");
    }

    /// <summary>AddrEdit.pas:52-56 `BtnApplyRowClick`：Value &lt; 1 时先钳到 1，再 RowCount := Value + 1。</summary>
    public static void BtnApplyRowClick(IStringGrid grid, ref int rowCountValue)
    {
        if (rowCountValue < 1) rowCountValue = 1;
        grid.RowCount = rowCountValue + 1;
    }

    /// <summary>
    /// AddrEdit.pas:58-74 `BtnApplyAndCloseClick` 的行文本构造：
    ///   行首列为空 → 追加**空串**（原文如此，会写出一行空行）；
    ///   非空 → `s14 + ' '`，再对第 1..ColCount-1 列逐个追加 `Trim(Cells[ii,i]) + ' '`（**尾部也有空格**）。
    /// </summary>
    public static List<string> BuildSaveLines(IStringGrid grid)
    {
        var SaveList = new List<string>();
        for (int i = 1; i <= grid.RowCount - 1; i++)
        {
            string s14 = DelphiRTL.Trim(grid.GetCell(0, i));
            if (s14 != "")
            {
                s14 = s14 + " ";
                for (int ii = 1; ii <= grid.ColCount - 1; ii++)
                {
                    s14 = s14 + DelphiRTL.Trim(grid.GetCell(ii, i)) + " ";
                }
            }
            SaveList.Add(s14);
        }
        return SaveList;
    }

    /// <summary>AddrEdit.pas:75-79 落盘（sGateConfFileName）；异常时 ShowMessage('... 保存异常！！！')。</summary>
    public static void SaveToFile(IStringGrid grid, string fileName)
    {
        var SaveList = new TStringList();
        foreach (string line in BuildSaveLines(grid)) SaveList.Add(line);
        try
        {
            SaveList.SaveToFile(fileName);
        }
        catch
        {
            UiSeam.ShowMessage(fileName + " 保存异常！！！");
        }
    }

    /// <summary>AddrEdit.pas:83-92 `sub_4A6864`：清空第 1..RowCount-1 行的全部列。</summary>
    public static void ClearDataCells(IStringGrid grid)
    {
        for (int i = 1; i <= grid.RowCount - 1; i++)
        {
            for (int ii = 0; ii <= grid.ColCount - 1; ii++)
            {
                grid.SetCell(ii, i, "");
            }
        }
    }

    /// <summary>
    /// AddrEdit.pas:94-131 `Open`（去掉末尾的 ShowModal，便于单测）：
    /// 清空 → 读 !ServerInfo.txt → 每行按 [空格/Tab] 拆成 1 + 2*4 列填入。
    /// 原文如此：一行若含 **超过 4 组** IP/端口，第 5 组会写到第 9/10 列（ColCount=9）→ 越界异常。
    /// </summary>
    public static void OpenInto(IStringGrid grid, string fileName)
    {
        ClearDataCells(grid);
        var LoadList = new TStringList();
        try
        {
            if (!File.Exists(fileName)) throw new FileNotFoundException(fileName);
            LoadList.LoadFromFile(fileName);
        }
        catch
        {
            UiSeam.ShowMessage(fileName + " 读取异常！！！");
        }
        int n1C = 1;
        for (int i = 0; i <= LoadList.Count - 1; i++)
        {
            string sStr = DelphiRTL.Trim(LoadList[i]);
            if ((sStr != "") && (sStr[0] != ';'))
            {
                string sStr1 = "";
                sStr = HUtil32.GetValidStr3(sStr, ref sStr1, new[] { ' ', '\t' });
                grid.SetCell(0, n1C, sStr1);
                int n18 = 0;
                while (true)
                {
                    if (sStr != "")
                    {
                        sStr = HUtil32.GetValidStr3(sStr, ref sStr1, new[] { ' ', '\t' });
                        grid.SetCell(n18 * 2 + 1, n1C, sStr1);
                        sStr = HUtil32.GetValidStr3(sStr, ref sStr1, new[] { ' ', '\t' });
                        grid.SetCell(n18 * 2 + 2, n1C, sStr1);
                        n18++;
                        if (n18 <= 4) continue;
                    }
                    n1C++;
                    if (grid.RowCount <= n1C)
                        grid.RowCount = grid.RowCount + 1;
                    break;
                }
            }
        }
    }
}

