    public readonly TStringGridModel Grid = new TStringGridModel(AddrEditLogic.ColCount, AddrEditLogic.InitialRowCount);

    public FrmEditAddr()
    {
        // DFM: FrmEditAddr Left=800 Top=525 Caption='游戏网关设置' ClientHeight=269 ClientWidth=763
        Text = "游戏网关设置";
        StartPosition = FormStartPosition.Manual;
