        ClientSize = new System.Drawing.Size(763, 269);
        FormBorderStyle = FormBorderStyle.Sizable;

        // DFM: AddrGrid Left=0 Top=0 Width=763 Height=228 Align=alClient ColCount=9 DefaultRowHeight=20
        //      FixedCols=0 RowCount=9 ColWidths=(106 100 55 98 46 100 64 103 56)
        AddrGrid = new DataGridView
        {
            Left = 0,
            Top = 0,
            Width = 763,
            Height = 228,
            AllowUserToAddRows = false,
            AllowUserToDeleteRows = false,
            RowHeadersVisible = false,
            ColumnCount = AddrEditLogic.ColCount,
            RowCount = AddrEditLogic.InitialRowCount
        };

        // DFM: Panel1 Left=0 Top=228 Width=763 Height=41 Align=alBottom BevelOuter=bvNone Caption=' '
        Panel1 = new Panel { Left = 0, Top = 228, Width = 763, Height = 41, BorderStyle = BorderStyle.None };
        // DFM: Label1 Left=8 Top=12 Width=30 Height=12 Caption='行数:'
        Label1 = new Label { Left = 8, Top = 12, Width = 30, Height = 12, Text = "行数:" };
        // DFM: BtnApplyRow Left=136 Top=8 Width=89 Height=22 Caption='设置行数(&S)' OnClick=BtnApplyRowClick
        BtnApplyRow = new Button { Left = 136, Top = 8, Width = 89, Height = 22, Text = "设置行数(&S)" };
        // DFM: BtnApplyAndClose Left=480 Top=8 Width=113 Height=25 Caption='确定(&O)' TabOrder=0 OnClick=BtnApplyAndCloseClick
        BtnApplyAndClose = new Button { Left = 480, Top = 8, Width = 113, Height = 25, Text = "确定(&O)", TabIndex = 0 };
        // DFM: ERowCount Left=56 Top=8 Width=73 Height=21 MaxValue=0 MinValue=0 TabOrder=1 Value=8
        ERowCount = new TSpinEdit { Left = 56, Top = 8, Width = 73, Height = 21, TabIndex = 1 };
