    /// <summary>AddrEdit.pas:38-50 `FormCreate`：ERowCount.Value := 8；写表头。</summary>
    public void FormCreate(object Sender, EventArgs e)
    {
        ERowCount.Value = 8;
        AddrEditLogic.FormCreate(Grid);
        SyncViewFromModel();
    }

    /// <summary>AddrEdit.pas:52-56 `BtnApplyRowClick`。</summary>
    public void BtnApplyRowClick(object Sender, EventArgs e)
    {
        int v = ERowCount.Value;
        AddrEditLogic.BtnApplyRowClick(Grid, ref v);
        ERowCount.Value = v;
        SyncViewFromModel();
    }

    /// <summary>AddrEdit.pas:58-81 `BtnApplyAndCloseClick`：建行 → 落盘 sGateConfFileName → Close。</summary>
    public void BtnApplyAndCloseClick(object Sender, EventArgs e)
    {
        SyncModelFromView();
        AddrEditLogic.SaveToFile(Grid, DBShareSeam.g_sGateConfFileName);
        Close();
    }

    /// <summary>AddrEdit.pas:94-133 `Open`：装载 → ShowModal。</summary>
    public void Open()
    {
        DoOpen();
        ShowDialog();
    }

    /// <summary>AddrEdit.pas:94-131 `Open` 主体（拆出以便单测；不含 ShowModal）。</summary>
    public void DoOpen()
    {
        AddrEditLogic.OpenInto(Grid, DBShareSeam.g_sGateConfFileName);
        SyncViewFromModel();
    }

    // ---------------- 模型 ↔ DataGridView 同步 ----------------

    public void SyncViewFromModel()
    {
        if (AddrGrid.ColumnCount != Grid.ColCount) AddrGrid.ColumnCount = Grid.ColCount;
        if (AddrGrid.RowCount != Grid.RowCount) AddrGrid.RowCount = Grid.RowCount;
        for (int r = 0; r < Grid.RowCount; r++)
            for (int c = 0; c < Grid.ColCount; c++)
                AddrGrid.Rows[r].Cells[c].Value = Grid.GetCell(c, r);
    }

    public void SyncModelFromView()
    {
        for (int r = 0; r < AddrGrid.RowCount && r < Grid.RowCount; r++)
            for (int c = 0; c < AddrGrid.ColumnCount && c < Grid.ColCount; c++)
                Grid.SetCell(c, r, Convert.ToString(AddrGrid.Rows[r].Cells[c].Value) ?? "");
    }
}
